"""Render original C/Gazebo angle, braking, yaw and lifecycle evidence."""
import json,math,hashlib
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[2]

def main():
 names=dict(short='manual-angle-hold-final-20261021',long='manual-long-angle-after-20261021-a',before='manual-long-angle-before-20261021',no_aiding='manual-no-aiding-final-20261021')
 runs={k:ROOT/'artifacts/gazebo-suite'/n for k,n in names.items()};results={k:json.loads((d/'result.json').read_text(encoding='utf8')) for k,d in runs.items()}
 out=ROOT/'artifacts/reports/manual-control-20261021';out.mkdir(parents=True,exist_ok=True)
 rows=[json.loads(x) for x in (runs['long']/'controller-trace.jsonl').read_text(encoding='utf8').splitlines()];t=np.array([r['time_s'] for r in rows]);tele=lambda k:np.array([r['telemetry'][k] for r in rows]);pos=np.array([r['position'] for r in rows]);vel=np.array([r['velocity'] for r in rows]);hold=tele('xy_hold_active')>0
 plt.style.use('dark_background');fig,axs=plt.subplots(3,2,figsize=(14,12))
 for ax,axis in zip(axs[0],['pitch','roll']):
  ax.plot(t,tele(axis+'_true'),label='Native true angle',lw=1.5);ax.plot(t,tele(axis+'_command'),'--',label='Actual C angle request',lw=1);ax.plot(t,tele(axis+'_est'),label='C Kalman estimate',lw=1,alpha=.75);ax.set(title=axis.title()+' · 4-second stick hold, then release',ylabel='Degrees');ax.legend(fontsize=9)
 axs[1,0].plot(t,np.linalg.norm(vel[:,:2],axis=1),label='Native horizontal speed');axs[1,0].fill_between(t,0,.15,where=hold,color='#4ddac5',alpha=.2,label='C hold active');axs[1,0].set(ylabel='m/s',title='Finite braking; no velocity reset');axs[1,0].legend(fontsize=9)
 error=np.hypot(pos[:,0]-tele('xy_target_x'),pos[:,1]-tele('xy_target_y'));error[~hold]=np.nan
 axs[1,1].plot(t,error);axs[1,1].set(ylabel='Metres',title='Distance to captured release point during hold')
 axs[2,0].plot(t,tele('yaw_true'),label='Native true heading');axs[2,0].set(ylabel='Degrees',title='Left-stick left → left yaw; right → right yaw');axs[2,0].legend(fontsize=9)
 axs[2,1].step(t,tele('angle_gravity_correction'),where='post',label='Gravity correction enabled');axs[2,1].plot(t,tele('xy_acceleration_norm'),label='Measured horizontal acceleration');axs[2,1].set(ylabel='Gate 0/1; acceleration m/s²',title='Translation is not treated as gravity');axs[2,1].legend(fontsize=9)
 for ax in axs.flat:ax.grid(alpha=.15);ax.set_xlabel('Simulation seconds')
 fig.suptitle('Actual C FC / native Gazebo · fixed HID commands · ideal external localization · assumed vehicle',fontsize=14);fig.tight_layout();fig.savefig(out/'control-graphs.png',dpi=140);plt.close(fig)
 engine=json.loads((runs['long']/'engine-summary.json').read_text(encoding='utf8'))
 summary=dict(passed=results['short']['passed'] and results['long']['passed'] and not results['before']['passed'] and not results['no_aiding']['passed'],runs=names,results=results,engine=engine['engine'],assumed_parameters=engine['assumed_parameters'],actual_FC_source_sha256=engine['sha256'].get('firmware/src/flight_controller.cpp',engine['sha256'].get('firmware/src/flight_controller.c')),actual_FC_binary_sha256=engine['sha256']['build/sitl/esp32_flight_core.dll'],scope='Native Gazebo 10.5/OGRE2, actual C host DLL, fixed raw HID sequence and no feedback pilot/ROS2. Perfect external localization sensor input is explicit. Not physical flight, BLE, real sensor timing or ESC validation. Failed trials are preserved.')
 (out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf8')
 metrics=results['long']['metrics'];table=''.join(f"<tr><td>{axis.title()}</td><td>{metrics[axis]['held_angle_mean_deg']:.3f}°</td><td>{metrics[axis]['release_point_error_m']*100:.2f} cm</td><td>{metrics[axis]['final_speed_mps']:.3f} m/s</td><td>{metrics[axis]['final_angle_deg']:.3f}°</td></tr>" for axis in ['pitch','roll'])
 video='../../gazebo-suite/'+names['long']+'/gazebo.mp4'
 html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IntelQCopter manual-control proof</title><style>body{{max-width:1200px;margin:30px auto;padding:20px;font:17px/1.6 system-ui;background:#102234;color:#e1edf5}}a{{color:#69dfc7}}img,video{{width:100%;border-radius:10px}}table{{border-collapse:collapse;width:100%;margin:25px 0}}th,td{{text-align:left;border-bottom:1px solid #3a536a;padding:12px}}.note{{padding:16px;border-left:4px solid #6dd5bd;background:#193247}}</style><h1>Angle → brake → level and hold</h1><p>Actual ESP32 C FC host build, native Gazebo physics/cameras and fixed raw Xbox-format commands. No ROS2 or feedback-based test pilot. This is a simulation test, not a real flight.</p><p class="note">Horizontal hold and dynamic gravity rejection explicitly use ideal simulated localization. The real IMU/barometer alone cannot supply this. Physical motor arming remains disabled.</p><h2>Final sustained-angle test: PASS</h2><p>Each stick requests 5° for four seconds. On release, the C FC captures the point, counter-tilts to brake, then levels and holds. Stopping is not instantaneous and can include overshoot.</p><table><tr><th>Axis</th><th>Held true angle (5° requested)</th><th>Error after 14s settling</th><th>Final horizontal speed</th><th>Final true angle</th></tr>{table}</table><video controls preload="metadata" src="{video}"></video><img src="control-graphs.png" alt="Original C control, native angles, speed, hold error and filter gating"><h2>Original failure preserved</h2><p>The longer test exposed accelerometer translation being mistaken for gravity: the earlier four-second hold reached mean pitch {results['before']['metrics']['pitch']['held_angle_mean_deg']:.2f}° and roll {results['before']['metrics']['roll']['held_angle_mean_deg']:.2f}° for a 5° request, then lost control. The updated C estimator retains gyro prediction/covariance and withholds contaminated gravity corrections during measured manual horizontal acceleration.</p><p><a href="../../gazebo-suite/{names['before']}/gazebo.mp4">Original failed video</a> · <a href="../../gazebo-suite/{names['before']}/result.json">Failed measurements</a></p><h2>Independent checks</h2><p>The shorter 1.2-second angle-step test also passed. A matching no-localization open-space test did not hold position, as expected; it remains a failed control case, with no hidden positioning helper. Both yaw directions passed against true native heading. Actual source/binary hashes and full assumed parameters are in the summary.</p><p><a href="summary.json">All results, hashes and assumptions</a> · <a href="../../gazebo-suite/{names['short']}/result.json">Short test</a> · <a href="../../gazebo-suite/{names['no_aiding']}/result.json">No-aiding control</a> · <a href="../../gazebo-suite/{names['long']}/predetermined-inputs.jsonl">Raw predetermined HID</a> · <a href="../../gazebo-suite/{names['long']}/flight.csv">Original 500Hz physics data</a> · <a href="../../gazebo-suite/{names['long']}/controller-trace.jsonl">C estimator/control trace</a></p><h2>Automatic recording and tabs</h2><p>Recording starts with the live session, without pressing Save. The home workshop opens its simulation in a new tab. End session stops physics and recording, waits for encoder completion, then closes that flight tab; the home stays open. Browser policy may require manual closing for tabs opened manually.</p></html>'''
 (out/'index.html').write_text(html,encoding='utf8');print('Rendered manual-control original-video/graph report');assert summary['passed']
if __name__=='__main__':main()
